59	  @Get()
60	  async listarRestaurantes(
61	    @Query()
62	    query: {
63	      state?: string;
64	      city?: string;
65	      neighborhood?: string;
66	      cep?: string;
67	      lat?: string;
68	      lng?: string;
69	      raio_km?: string;
70	    },
71	    @Headers('authorization') authorization?: string,
72	  ) {
73	    // Sem Authorization o resultado é puramente função da querystring — cacheável.
74	    // Com Authorization pode depender do endereço salvo do cliente (personalizado), então
75	    // nesse caso sempre busca direto no Supabase, igual já fazia antes do cache.
76	    const cacheKey = !authorization
77	      ? `catalogo:home:${JSON.stringify(query, Object.keys(query).sort())}`
78	      : null;
79	
80	    if (cacheKey) {
81	      const cached = await this.redis.getJSON<{ restaurantes: any[] }>(cacheKey);
82	      if (cached) return cached;
83	    }
84	
85	    let q = this.supabase.client
86	      .from('restaurants')
87	      .select('id, name, address, state, city, neighborhood, cep, logo_url, slug, aparencia, frete_motoboy, lat, lng')
88	      .not('slug', 'is', null)
89	      .eq('bloqueado', false);
90	
91	    if (query.state) q = q.ilike('state', query.state);
92	    if (query.city) q = q.ilike('city', query.city);
93	    if (query.neighborhood) q = q.ilike('neighborhood', query.neighborhood);
94	    if (query.cep) q = q.ilike('cep', `${query.cep.replace(/\D/g, '').slice(0, 5)}%`);
95	
96	    const { data, error } = await q.order('name');
97	    if (error) throw error;
98	
99	    let restaurantes = data ?? [];
100	
101	    // Filtro/ordenação por proximidade — GPS ao vivo do navegador é a fonte principal
102	    // (comportamento esperado: cliente abre o site, mostra estabelecimentos perto de onde
103	    // ele está agora). Só cai pro endereço salvo/geocodificado do perfil (ver PerfilService)
104	    // quando o navegador não mandou lat/lng (GPS negado/indisponível) e o cliente tem token
105	    // válido — nunca confia numa coordenada de "fallback" vinda do próprio client.
106	    let lat = query.lat ? parseFloat(query.lat) : null;
107	    let lng = query.lng ? parseFloat(query.lng) : null;
108	    let usandoEnderecoSalvo = false;
109	
110	    if (lat == null && lng == null && authorization?.startsWith('Bearer ')) {
111	      const token = authorization.slice('Bearer '.length);
112	      const payload = await this.supabaseJwt.verificar(token);
113	      if (payload?.sub) {
114	        const { data: customer } = await this.supabase.client
115	          .from('customers')
116	          .select('lat, lng')
117	          .eq('user_id', payload.sub)
118	          .maybeSingle();
119	        if (customer?.lat != null && customer?.lng != null) {
120	          lat = customer.lat;
121	          lng = customer.lng;
122	          usandoEnderecoSalvo = true;
123	        }
124	      }
125	    }
126	
127	    if (lat != null && lng != null && !Number.isNaN(lat) && !Number.isNaN(lng)) {
128	      const raioKm = query.raio_km ? parseFloat(query.raio_km) : (usandoEnderecoSalvo ? RAIO_KM_PADRAO : null);
129	      restaurantes = restaurantes
130	        .map((r) => ({
131	          ...r,
132	          // 3 casas decimais (precisão de metro) — raios pequenos (20m, 50m...)
133	          // precisavam de mais que os 100m que 1 casa decimal dava.
134	          distancia_km:
135	            r.lat != null && r.lng != null
136	              ? Math.round(haversineKm({ lat, lng }, { lat: r.lat, lng: r.lng }) * 1000) / 1000
137	              : null,
138	        }))
139	        .filter((r) => raioKm == null || (r.distancia_km != null && r.distancia_km <= raioKm))
140	        .sort((a, b) => (a.distancia_km ?? Infinity) - (b.distancia_km ?? Infinity));
141	    }
142	
143	    const resultado = { restaurantes };
144	    if (cacheKey) await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
145	    return resultado;
146	  }
147	
148	  // Valores distintos de estado/cidade/bairro entre restaurantes ativos — alimenta os
149	  // dropdowns em cascata do filtro geográfico na home pública (evita carregar tudo só
150	  // pra montar as opções). Precisa vir ANTES de @Get(':slug') na ordem das rotas.
151	  @Get('filtros')
152	  async filtrosGeograficos() {
153	    const cacheKey = 'catalogo:filtros';
154	    const cached = await this.redis.getJSON<{ locais: any[] }>(cacheKey);
155	    if (cached) return cached;
156	
157	    const { data, error } = await this.supabase.client
158	      .from('restaurants')
159	      .select('state, city, neighborhood')
160	      .not('slug', 'is', null)
161	      .eq('bloqueado', false);
162	    if (error) throw error;
163	
164	    const vistos = new Set<string>();
165	    const locais: { state: string | null; city: string | null; neighborhood: string | null }[] = [];
166	    for (const r of data ?? []) {
167	      if (!r.state && !r.city && !r.neighborhood) continue;
168	      const key = `${r.state ?? ''}|${r.city ?? ''}|${r.neighborhood ?? ''}`;
169	      if (vistos.has(key)) continue;
170	      vistos.add(key);
171	      locais.push({ state: r.state, city: r.city, neighborhood: r.neighborhood });
172	    }
173	    const resultado = { locais };
174	    await this.redis.setJSON(cacheKey, resultado, TTL_FILTROS);
175	    return resultado;
176	  }
177	
178	  @Get('produtos')
179	  async todosOsProdutos() {
180	    const cacheKey = 'catalogo:produtos:marketplace';
181	    const cached = await this.redis.getJSON<{ produtos: any[] }>(cacheKey);
182	    if (cached) return cached;
183	
184	    const { data: restaurantes } = await this.supabase.client
185	      .from('restaurants')
186	      .select('id, name, logo_url, slug, aparencia, frete_motoboy')
187	      .not('slug', 'is', null)
188	      .eq('bloqueado', false);
189	
190	    if (!restaurantes?.length) return { produtos: [] };
191	
192	    const restIds = restaurantes.map((r) => r.id);
193	    const restMap = Object.fromEntries(restaurantes.map((r) => [r.id, r]));
194	
195	    // Busca diretamente por restaurant_id (não depende de category chain)
196	    const { data: produtos, error } = await this.supabase.client
197	      .from('products')
198	      .select(PRODUTO_FIELDS)
199	      .eq('is_active', true)
200	      .gt('quantidade_estoque', 0)
201	      .in('restaurant_id', restIds)
202	      .order('name')
203	      .limit(200);
204	
205	    if (error) throw error;
206	
207	    const resultado = {
208	      produtos: (produtos ?? []).map((p) => ({
209	        ...p,
210	        restaurante: restMap[p.restaurant_id] ?? null,
211	      })).filter((p) => p.restaurante),
212	    };
213	    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
214	    return resultado;
215	  }
216	
217	  // Marketplace (home sem domínio customizado): combo ativo de todos os
218	  // estabelecimentos, com estoque de todo ingrediente — mesmo critério
219	  // de disponibilidade do CombosService, só que sem restringir a 1 restaurante.
220	  @Get('combos')
221	  async todosOsCombos() {
222	    const cacheKey = 'catalogo:combos:marketplace';
223	    const cached = await this.redis.getJSON<{ combos: any[] }>(cacheKey);
224	    if (cached) return cached;
225	
226	    const { data: restaurantes } = await this.supabase.client
227	      .from('restaurants')
228	      .select('id, name, logo_url, slug, aparencia, frete_motoboy')
229	      .not('slug', 'is', null)
230	      .eq('bloqueado', false);
231	
232	    if (!restaurantes?.length) return { combos: [] };
233	
234	    const restIds = restaurantes.map((r) => r.id);
235	    const restMap = Object.fromEntries(restaurantes.map((r) => [r.id, r]));
236	
237	    const { data: combos, error } = await this.supabase.client
238	      .from('combos')
239	      .select(
240	        'id, name, description, price, preco_promo, image_url, destaque, restaurant_id, is_active, combo_items(quantity, products(quantidade_estoque, is_active))',
241	      )
242	      .eq('is_active', true)
243	      .in('restaurant_id', restIds)
244	      .order('destaque', { ascending: false })
245	      .order('name')
246	      .limit(200);
247	
248	    if (error) throw error;
249	
250	    const resultado = {
251	      combos: (combos ?? [])
252	        .map((c: any) => {
253	          const { combo_items, ...resto } = c;
254	          const itens = combo_items ?? [];
255	          const disponivel =
256	            itens.length > 0 &&
257	            itens.every((ci: any) => ci.products?.is_active && (ci.products?.quantidade_estoque ?? 0) > 0);
258	          return { ...resto, disponivel, restaurante: restMap[c.restaurant_id] ?? null };
259	        })
260	        .filter((c: any) => c.disponivel && c.restaurante),
261	    };
262	    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
263	    return resultado;
264	  }
265	
266	  // Resolução de domínio customizado — precisa vir ANTES de @Get(':slug') na
267	  // ordem das rotas (mesma regra de 'filtros'/'produtos' acima).
268	  @Get('by-domain/:host')
269	  async cardapioPorDominio(@Param('host') host: string) {
270	    const dominio = normalizarDominio(host);
271	    const cacheKey = `catalogo:cardapio:dominio:${dominio}`;
272	    const cached = await this.redis.getJSON<any>(cacheKey);
273	    if (cached) return cached;
274	
275	    const { data: restaurante } = await this.supabase.client
276	      .from('restaurants')
277	      .select('id, name, address, logo_url, business_hours, slug, aparencia, frete_motoboy')
278	      .eq('custom_domain', dominio)
279	      .maybeSingle();
280	
281	    if (!restaurante) throw new NotFoundException('Domínio não configurado');
282	    const resultado = await this.montarCardapio(restaurante);
283	    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
284	    return resultado;
285	  }
286	
287	  @Get(':slug')
288	  async cardapio(@Param('slug') slug: string) {
289	    const cacheKey = `catalogo:cardapio:${slug}`;
290	    const cached = await this.redis.getJSON<any>(cacheKey);
291	    if (cached) return cached;
292	
293	    const { data: restaurante } = await this.supabase.client
294	      .from('restaurants')
295	      .select('id, name, address, logo_url, business_hours, slug, aparencia, frete_motoboy')
296	      .eq('slug', slug)
297	      .maybeSingle();
298	
299	    if (!restaurante) throw new NotFoundException('Restaurante não encontrado');
300	    const resultado = await this.montarCardapio(restaurante);
301	    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
302	    return resultado;
303	  }
304	
305	  private async montarCardapio(restaurante: any) {
306	    // Categorias do restaurante (próprias + globais para exibição)
307	    const { data: categorias } = await this.supabase.client
308	      .from('categories')
309	      .select('id, name')
310	      .or(`restaurant_id.eq.${restaurante.id},restaurant_id.is.null`)
311	      .order('name');
312	
313	    // Produtos via restaurant_id (forma correta e direta)
314	    const { data: produtos } = await this.supabase.client
315	      .from('products')
316	      .select(PRODUTO_FIELDS)
317	      .eq('is_active', true)
318	      .gt('quantidade_estoque', 0)
319	      .eq('restaurant_id', restaurante.id)
320	      .order('destaque', { ascending: false })
321	      .order('name');
322	
323	    const cardapio = (categorias ?? []).map((cat) => ({
324	      ...cat,
325	      produtos: (produtos ?? []).filter((p) => p.category_id === cat.id),
326	    })).filter((cat) => cat.produtos.length > 0);
327	
328	    const destaques = (produtos ?? []).filter((p) => p.destaque);
329	    const promos = (produtos ?? []).filter(
330	      (p) => Array.isArray(p.tags) && p.tags.includes('promo') && p.preco_promo != null,
331	    );
332	
333	    // Combos são entidade separada de products — mesmos campos de exibição
334	    // (name/price/preco_promo/image_url/destaque) pra reusar o mesmo card do cliente.
335	    // Some do cardápio se faltar estoque de qualquer produto que o compõe.
336	    const combosDisponiveis = await this.combosService.listarComDisponibilidade(restaurante.id);
337	    const combos = combosDisponiveis.filter((c) => c.disponivel).map((c) => ({ ...c, tipo: 'combo' }));
338	
339	    return { restaurante, cardapio, destaques, promos, combos };
340	  }
341	}
