636	/* ── Componente principal ────────────────────────────────────────── */
637	const MenuCatalogProductBrowse = () => {
638	  const navigate = useNavigate();
639	  const { isAuthenticated, isAdmin, isRestaurantOwner, signOut, userProfile } = useAuth();
640	
641	  const [restaurantes, setRestaurantes] = useState([]);
642	  const [produtos, setProdutos]         = useState([]);
643	  const [combos, setCombos]             = useState([]);
644	  const [categorias, setCategorias]     = useState(CATEGORIAS_FALLBACK);
645	  const [tagsCatalogo, setTagsCatalogo] = useState([]); // tags ativas do admin
646	  const [loading, setLoading]           = useState(true);
647	  const [loadProd, setLoadProd]         = useState(true);
648	  const [erro, setErro]                 = useState(null);
649	  const [busca, setBusca]               = useState('');
650	  const [catAtiva, setCatAtiva]         = useState(null);
651	  const [viewMode, setViewMode]         = useState('grid');
652	  const [badgeCount, setBadgeCount]     = useState(() => cartCount());
653	  const [badgeTotal, setBadgeTotal]     = useState(() => cartTotal());
654	  const [perfilCliente, setPerfilCliente] = useState(null);
655	
656	  // Filtro geográfico — localização automática (GPS do navegador) + filtros manuais
657	  // de Estado/Cidade/Bairro/CEP. Sem filtro manual ativo, a localização já limita a
658	  // lista ao raio escolhido automaticamente (cliente não precisa mexer em nada).
659	  const [localizacao, setLocalizacao]     = useState(null); // { lat, lng } | null
660	  const [statusLocalizacao, setStatusLocalizacao] = useState('pedindo'); // pedindo|ok|negado|indisponivel
661	  const [raioKm, setRaioKm]               = useState(15);
662	  const [locaisFiltro, setLocaisFiltro]   = useState([]);
663	  const [filtroEstado, setFiltroEstado]   = useState('');
664	  const [filtroCidade, setFiltroCidade]   = useState('');
665	  const [filtroBairro, setFiltroBairro]   = useState('');
666	  const [filtroCep, setFiltroCep]         = useState('');
667	
668	  const pedirLocalizacao = () => {
669	    if (!navigator.geolocation) { setStatusLocalizacao('indisponivel'); return; }
670	    setStatusLocalizacao('pedindo');
671	    navigator.geolocation.getCurrentPosition(
672	      (pos) => { setLocalizacao({ lat: pos.coords.latitude, lng: pos.coords.longitude }); setStatusLocalizacao('ok'); },
673	      () => setStatusLocalizacao('negado'),
674	      { timeout: 8000 },
675	    );
676	  };
677	
678	  const limparFiltrosGeo = () => {
679	    setFiltroEstado(''); setFiltroCidade(''); setFiltroBairro(''); setFiltroCep('');
680	  };
681	
682	  const temFiltroManual = !!(filtroEstado || filtroCidade || filtroBairro || filtroCep);
683	  const estadosDisponiveis = [...new Set(locaisFiltro.map((l) => l.state).filter(Boolean))].sort();
684	  const cidadesDisponiveis = [...new Set(
685	    locaisFiltro.filter((l) => !filtroEstado || l.state === filtroEstado).map((l) => l.city).filter(Boolean),
686	  )].sort();
687	  const bairrosDisponiveis = [...new Set(
688	    locaisFiltro
689	      .filter((l) => (!filtroEstado || l.state === filtroEstado) && (!filtroCidade || l.city === filtroCidade))
690	      .map((l) => l.neighborhood).filter(Boolean),
691	  )].sort();
692	
693	  const handleAddToCart = (produto, restaurante) => {
694	    cartAdd(produto, restaurante);
695	    setBadgeCount(cartCount());
696	    setBadgeTotal(cartTotal());
697	  };
698	
699	  const handleIrCheckout = () => {
700	    if (!isAuthenticated()) {
701	      sessionStorage.setItem('pending_multi_cart', '1');
702	      navigate('/customer-registration-login', { state: { from: '/shopping-cart-checkout' } });
703	      return;
704	    }
705	    navigate('/shopping-cart-checkout', { state: { multiCart: true } });
706	  };
707	
708	  const mediaNota = restaurantes.length > 0
709	    ? restaurantes.reduce((acc, r) => acc + (r.nota ?? 4.5), 0) / restaurantes.length
710	    : 0;
711	
712	  useEffect(() => {
713	    pedirLocalizacao();
714	    // Rede de segurança: se o navegador nunca resolver o pedido de permissão (usuário
715	    // deixa o diálogo aberto), não trava a home esperando pra sempre.
716	    const fallback = setTimeout(() => setStatusLocalizacao((s) => (s === 'pedindo' ? 'negado' : s)), 10000);
717	
